# Simpler approach - load grids using the helper from the prompt
import os, re

session_dir = os.getenv('RLM_SESSION_DIR')
if not session_dir:
    session_dir = os.path.dirname(os.path.dirname(os.path.dirname(os.getcwd())))
jsonl_path = os.path.join(session_dir, 'sessions', os.path.basename(session_dir) + '.jsonl')

def load_g():
    if not os.path.exists(jsonl_path):
        return {}
    content = open(jsonl_path).read()
    G = {}
    # Find markers like "Demo pair 1 input (13x16):"
    for match in re.finditer(r'(Demo pair \d+\s+(?:input|output)\s+\(\d+x\d+\)):\n', content):
        key = match.group(1)
        m = match.span()[1]
        end = content.find('\nDemo ', m)
        if end == -1:
            end = len(content)
        rows = content[m:end].strip().split('\n')[:13]
        if key not in G and len(rows) > 0:
            if all(len(r) > 0 and all(x.strip().isdigit() for x in r.split()) for r in rows):
                G[key] = [[int(x.strip()) for x in r.split()] for r in rows]
    return G

G = load_g()
print("Loaded:", sorted(G.keys()))
for k in G:
    print(f"{k}: {len(G[k])}x{len(G[k][0])}")

def transform_complete(grid):
    """Complete transformation function."""
    from collections import deque

    h, w = len(grid), len(grid[0])

    # Find all boxes with properties
    visited = [[False]*w for _ in range(h)]
    boxes = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] > 0 and not visited[r][c]:
                color = grid[r][c]
                pixels = []
                queue = deque([(r,c)])
                visited[r][c] = True
                while queue:
                    pr, pc = queue.popleft()
                    pixels.append((pr, pc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = pr + dr, pc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                rows = [p[0] for p in pixels]
                cols = [p[1] for p in pixels]
                bh = max(rows) - min(rows) + 1
                bw = max(cols) - min(cols) + 1
                density = len(pixels) / (bh * bw) if bh * bw > 0 else 0
                boxes.append({
                    'color': color, 'height': bh, 'width': bw, 'density': density,
                    'orig_r': min(rows), 'orig_c': min(cols)
                })

    # Sort by density descending
    sorted_boxes = sorted(boxes, key=lambda b: -b['density'])

    result = [[0]*w for _ in range(h)]

    # Place top 2 dense boxes as hollow boxes at cols 1, 5
    for i, box in enumerate(sorted_boxes[:2]):
        col_start = i * 4 + 1
        for dr in range(box['height']):
            for dc in range(box['width']):
                is_outer_edge = (dr == 0 or dr == box['height']-1) or (dc == 0 or dc == box['width']-1)
                if is_outer_edge:
                    result[dr][col_start + dc] = box['color']

    # Place remaining boxes at bottom rows (10-12)
    remaining = sorted(sorted_boxes[2:], key=lambda b: b['orig_c'])  # Sort by original col

    # Row 12: concatenate all remaining boxes horizontally at first box column
    if remaining:
        start_col = remaining[0]['orig_c']
        row_12 = [0] * start_col
        for box in remaining:
            row_12 += [box['color']] * box['width']
        for c, val in enumerate(row_12):
            result[12][c] = val if c < w else 0

    # Row 11: each box gets a pixel (last or middle?) at certain position based on box
    if len(remaining) >= 2:
        row_11 = [0] * w
        row_11[start_col + remaining[0]['width']] = remaining[0]['color']  # +start_col + width
        for i, box in enumerate(remaining):
            if len(remaining) > i + 1:
                row_11[start_col + remaining[i]['width']] = box['color']
                # or some other position...
        for c, val in enumerate(row_11):
            if c < w:
                result[11][c] = val  # placeholder

    return result

