def transform_arc(grid):
    """Complete ARC transformation function."""
    from collections import deque

    h, w = len(grid), len(grid[0])

    # Step 1: Extract all connected component boxes
    visited = [[False] * w for _ in range(h)]
    boxes = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] > 0 and not visited[r][c]:
                color = grid[r][c]
                pixels = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    pr, pc = queue.popleft()
                    pixels.append((pr, pc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = pr + dr, pc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))

                rows = {p[0] for p in pixels}
                cols = {p[1] for p in pixels}
                bh = max(rows) - min(rows) + 1
                bw = max(cols) - min(cols) + 1
                density = len(pixels) / (bh * bw)
                boxes.append({
                    'color': color, 'height': bh, 'width': bw,
                    'pixels': len(pixels), 'density': density,
                    'orig_r': min(rows), 'orig_c': min(cols)
                })

    # Sort by density descending
    sorted_boxes = sorted(boxes, key=lambda b: -b['density'])

    # Separate hollow (perimeter) vs solid fragments
    def is_hollow(box):
        return box['pixels'] == (2 * box['height'] + 2 * box['width'] - 4)

    hollow = [b for b in sorted_boxes if is_hollow(b)]
    fragments = [b for b in sorted_boxes if not is_hollow(b)]

    # Step 2: Create output grid
    result = [[0] * w for _ in range(h)]

    # Step 3: Place hollow boxes in top rows (0, 1, 2...) at orig_c
    for box in hollow:
        col_start = box['orig_c']
        for row in range(box['height']):
            for col in range(box['width']):
                is_border = (row == 0 or row == box['height'] - 1 or 
                            col == 0 or col == box['width'] - 1)
                if is_border:
                    result[row][col_start + col] = box['color']

    # Step 4: Place fragments in rows 10-12
    # Sort fragments by orig_c for consistent placement
    fragments_sorted = sorted(fragments, key=lambda b: b['orig_c'])

    if fragments_sorted:
        row_10 = [0] * w
        row_11 = [0] * w
        row_12 = [0] * w

        for box in fragments_sorted:
            # Row 10 and 12: markers at center of box (orig_c + round(w/2))
            marker_c = box['orig_c'] + round(box['width'] / 2)
            if marker_c < w:
                row_10[marker_c] = box['color']
                row_12[marker_c] = box['color']

            # Row 11: full box starting at orig_c
            for dc in range(box['width']):
                if box['orig_c'] + dc < w:
                    row_11[box['orig_c'] + dc] = box['color']

        for c in range(w):
            result[10][c] = row_10[c]
            result[11][c] = row_11[c]
            result[12][c] = row_12[c]

    return result

