"""
Key insight: render ALL hollow boxes at row 0 (not stacked), each uses its actual height.

D1 expected shows:
- Color 1 (height=3): row 0-2 at c=1-3
- Color 8 (height=4): row 0-3 at c=5-7

This means NO stacking of hollow boxes in top rows.
Each hollow box renders at row 0 using its inherent height.
"""
from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]
    boxes = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] > 0 and not visited[r][c]:
                color = grid[r][c]
                queue = deque([(r, c)])
                visited[r][c] = True
                pixels = []
                while queue:
                    pr, pc = queue.popleft()
                    pixels.append((pr, pc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = pr + dr, pc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))

                rows = {p[0] for p in pixels}
                cols = {p[1] for p in pixels}
                bh, bw = max(rows) - min(rows) + 1, max(cols) - min(cols) + 1
                density = len(pixels) / (bh * bw)
                boxes.append({
                    'color': color, 'height': bh, 'width': bw,
                    'density': density, 'orig_c': min(cols)
                })

    sorted_boxes = sorted(boxes, key=lambda b: -b['density'])

    if len(sorted_boxes) > 0:
        max_dens = sorted_boxes[0]['density']
        min_dens = sorted_boxes[-1]['density']
        midpoint_threshold = (max_dens + min_dens) / 2
    else:
        midpoint_threshold = 0.5

    def get_band(box):
        return 'top' if box['density'] > midpoint_threshold else 'bottom'

    bottom_sorted = sorted([b for b in sorted_boxes if get_band(b) == 'bottom'], key=lambda b: b['orig_c'])
    result = [[0] * w for _ in range(h)]

    def render_hollow(box, row_start):
        col_start = box['orig_c']
        bh, bw = box['height'], box['width']
        for row in range(bh):
            for col in range(bw):
                is_border = row == 0 or row == bh - 1 or col == 0 or col == bw - 1
                if is_border:
                    result[row_start + row][col_start + col] = box['color']

    # Render all top boxes starting at row 0 (no stacking)
    for box in sorted_boxes:
        if get_band(box) == 'top':
            render_hollow(box, 0)

    # Initialize bottom rows
    for c in range(w): result[10][c] = result[11][c] = result[12][c] = 0

    # Place bottom fragments
    if bottom_sorted:
        for box in bottom_sorted:
            marker_c = box['orig_c'] + box['width'] // 2
            if marker_c < w:
                result[10][marker_c] = box['color']
                result[12][marker_c] = box['color']
            for dc in range(box['width']):
                if box['orig_c'] + dc < w:
                    result[11][box['orig_c'] + dc] = box['color']

    return result

print("Testing all demos with NO stacking:")
all_pass = True
for name, inp, exp in [("D1", demo_1_in, demo_1_out), ("D2", demo_2_in, demo_2_out), ("D3", demo_3_in, demo_3_out)]:
    result = transform(inp)
    all_match = all(result[i] == exp[i] for i in range(len(exp)))
    status = "✓" if all_match else "✗"
    print(f"{status} {name}")
    if not all_match:
        for i in range(min(len(result), len(exp))):
            if result[i] != exp[i]:
                print(f"  First diff at row {i}: got {result[i]}, expected {exp[i]}")
